package com.collabspace.controller; import com.collabspace.dto.MessageDtos.*;import com.collabspace.service.DirectMessageService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/conversations") @RequiredArgsConstructor public class DirectMessageController {private final DirectMessageService s; @PostMapping("/{userId}/messages") public DirectMessageResponse send(@PathVariable UUID userId,@Valid @RequestBody SendDirectMessageRequest r){return s.send(userId,r);}@GetMapping("/{userId}/messages") public Page<DirectMessageResponse> history(@PathVariable UUID userId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return s.history(userId,page,size);}}